package clickhouse_api

import (
	"context"
	"fmt"
	"github.com/shopspring/decimal"
)

func ReadWriteDecimal() error {
	conn, err := GetNativeConnection(nil, nil, nil)
	if err != nil {
		return err
	}
	ctx := context.Background()
	if err != nil {
		return err
	}
	conn.Exec(ctx, "DROP TABLE IF EXISTS example")

	if err = conn.Exec(ctx, `
		CREATE TABLE example (
			Col1 Decimal32(3), 
			Col2 Decimal(18,6), 
			Col3 Decimal(15,7), 
			Col4 Decimal128(8), 
			Col5 Decimal256(9)
		) Engine Memory
		`); err != nil {
		return err
	}

	batch, err := conn.PrepareBatch(ctx, "INSERT INTO example")
	if err != nil {
		return err
	}
	if err = batch.Append(
		decimal.New(25, 4),
		decimal.New(30, 5),
		decimal.New(35, 6),
		decimal.New(135, 7),
		decimal.New(256, 8),
	); err != nil {
		return err
	}

	if err = batch.Send(); err != nil {
		return err
	}

	var (
		col1 decimal.Decimal
		col2 decimal.Decimal
		col3 decimal.Decimal
		col4 decimal.Decimal
		col5 decimal.Decimal
	)

	if err = conn.QueryRow(ctx, "SELECT * FROM example").Scan(&col1, &col2, &col3, &col4, &col5); err != nil {
		return err
	}
	fmt.Printf("col1=%v, col2=%v, col3=%v, col4=%v, col5=%v\n", col1, col2, col3, col4, col5)
	return nil
}

package clickhouse_api

import (
	"fmt"
	"log/slog"
	"os"

	"github.com/ClickHouse/clickhouse-go/v2"
)

func Logger() error {
	env, err := GetNativeTestEnvironment()
	if err != nil {
		return err
	}

	// Create a structured logger with JSON output
	logger := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{
		Level: slog.LevelDebug,
	}))

	conn, err := clickhouse.Open(&clickhouse.Options{
		Addr: []string{fmt.Sprintf("%s:%d", env.Host, env.Port)},
		Auth: clickhouse.Auth{
			Database: env.Database,
			Username: env.Username,
			Password: [REDACTED],
		},
		Logger: logger,
	})
	if err != nil {
		return err
	}
	defer conn.Close()

	// All connection operations will now be logged with structured fields
	// Output will include fields like: conn_id, remote_addr, protocol, etc.
	return nil
}

func LegacyDebug() error {
	env, err := GetNativeTestEnvironment()
	if err != nil {
		return err
	}
	conn, err := clickhouse.Open(&clickhouse.Options{
		Addr: []string{fmt.Sprintf("%s:%d", env.Host, env.Port)},
		Auth: clickhouse.Auth{
			Database: env.Database,
			Username: env.Username,
			Password: [REDACTED],
		},
		Debug: true,
		Debugf: func(format string, v ...any) {
			fmt.Printf("[LEGACY] "+format+"\n", v...)
		},
	})
	if err != nil {
		return err
	}
	defer conn.Close()

	// Legacy Debugf will be called for all log messages
	return nil
}

func TextLogger() error {
	env, err := GetNativeTestEnvironment()
	if err != nil {
		return err
	}
	logger := slog.New(slog.NewTextHandler(os.Stdout, &slog.HandlerOptions{
		Level: slog.LevelDebug,
	}))

	conn, err := clickhouse.Open(&clickhouse.Options{
		Addr: []string{fmt.Sprintf("%s:%d", env.Host, env.Port)},
		Auth: clickhouse.Auth{
			Database: env.Database,
			Username: env.Username,
			Password: [REDACTED],
		},
		Logger: logger,
	})
	if err != nil {
		return err
	}
	defer conn.Close()

	// Logs will be output in human-readable text format
	// Example: time=2024-01-21T10:00:00.000Z level=DEBUG msg="query" sql="SELECT 1" conn_id=1
	return nil
}

func EnrichedLogger() error {
	env, err := GetNativeTestEnvironment()
	if err != nil {
		return err
	}
	baseLogger := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{
		Level: slog.LevelInfo,
	}))

	// Add application-level context
	enrichedLogger := baseLogger.With(
		slog.String("service", "my-service"),
		slog.String("environment", "production"),
		slog.String("version", "1.0.0"),
	)

	conn, err := clickhouse.Open(&clickhouse.Options{
		Addr: []string{fmt.Sprintf("%s:%d", env.Host, env.Port)},
		Auth: clickhouse.Auth{
			Database: env.Database,
			Username: env.Username,
			Password: [REDACTED],
		},
		Logger: enrichedLogger,
	})
	if err != nil {
		return err
	}
	defer conn.Close()

	// All logs will include service, environment, and version fields
	// in addition to the connection-specific fields
	return nil
}

